"""The interactive replay viewer (REPLAY-01, REPLAY-02, AD-07)."""

from typing import Literal

import matplotlib.pyplot as plt
import numpy as np
from matplotlib.axes import Axes
from matplotlib.backend_bases import KeyEvent, TimerBase
from matplotlib.colors import ListedColormap
from matplotlib.patches import Circle

from rllab.runs import GameRecording

# Grid cell codes: 0 empty, 1 head, 2 body, 3 food or goal.
CELL_COLOURS = ListedColormap(["white", "darkgreen", "limegreen", "red"])
# Tank circle kinds: 0 ball, 1 fish, 2 caught fish, 3 predator, 4 prey, 5 caught prey, 6 pellet.
KIND_COLOURS = ("lightblue", "tab:orange", "grey", "tab:red", "tab:green", "grey", "olive")


class Replay:
    """Draws a recorded game frame by frame; space pauses, right arrow steps, +/- change fps."""

    def __init__(self, game: GameRecording, *, fps: float = 8.0) -> None:
        self._game = game
        self._fps = fps
        self._index = 0
        self._paused = False

    @property
    def fps(self) -> float:
        """Frames per second while playing."""
        return self._fps

    @property
    def index(self) -> int:
        """The frame drawn now."""
        return self._index

    @property
    def paused(self) -> bool:
        """Whether the timer stopped advancing."""
        return self._paused

    def current(self) -> tuple[np.ndarray, dict[str, float], int]:
        """The frame drawn now, each team's score at it, and its step."""
        i = self._index
        scores = {team: float(values[i]) for team, values in self._game.scores.items()}
        return self._game.frames[i], scores, i

    def advance(self) -> int:
        """Move one frame on and return its index, stopping at the last frame."""
        self._index = min(self._index + 1, self._game.frames.shape[0] - 1)
        return self._index

    def on_key(self, key: str) -> None:
        """Space toggles pause, right arrow steps, `+`/`-` double or halve fps; others do nothing."""
        if key == " ":
            self._paused = not self._paused
        elif key == "right":
            self.advance()
        elif key == "+":
            self._fps *= 2
        elif key == "-":
            self._fps /= 2

    def show(self) -> None:
        """Open the window and play; blocks until it closes."""
        fig, ax = plt.subplots()
        timer = fig.canvas.new_timer(interval=self._interval_ms())

        def redraw() -> None:
            frame, scores, step = self.current()
            draw_frame(ax, self._game.board, frame, title(scores, step))
            fig.canvas.draw_idle()

        def key_pressed(event: KeyEvent) -> None:
            if event.key is not None:
                self.on_key(event.key)
                redraw()

        def tick(timer: TimerBase) -> None:
            timer.interval = self._interval_ms()
            if not self._paused:
                self.advance()
                redraw()

        fig.canvas.mpl_connect("key_press_event", key_pressed)
        timer.add_callback(tick, timer)
        redraw()
        timer.start()
        plt.show()
        timer.stop()
        plt.close(fig)

    def _interval_ms(self) -> int:
        return max(1, round(1000 / self._fps))


def title(scores: dict[str, float], step: int) -> str:
    """The step and each team's score, on one line."""
    parts = [f"step {step}", *(f"{team} {score:g}" for team, score in scores.items())]
    return " · ".join(parts)


def draw_frame(ax: Axes, board: Literal["grid", "tank"], frame: np.ndarray, label: str) -> None:
    """Draw one frame on `ax`: grid cells as an image, or tank circles coloured by kind."""
    ax.clear()
    ax.set_title(label)
    ax.set_xticks([])
    ax.set_yticks([])
    if board == "grid":
        ax.imshow(frame, cmap=CELL_COLOURS, vmin=0, vmax=len(CELL_COLOURS.colors) - 1)
        return
    for x, y, radius, kind in frame:
        ax.add_patch(Circle((float(x), float(y)), float(radius), color=KIND_COLOURS[int(kind)]))
    ax.set_xlim(float((frame[:, 0] - frame[:, 2]).min()), float((frame[:, 0] + frame[:, 2]).max()))
    ax.set_ylim(float((frame[:, 1] - frame[:, 2]).min()), float((frame[:, 1] + frame[:, 2]).max()))
    ax.set_aspect("equal")

